<script setup lang="ts">
import {onMounted,ref} from 'vue';import {api,apiMessage} from '@/api/client';import {adminNavigation} from '@/adminCenter';
interface Overview{observedAt:string;members:number;enabledMembers:number;activeInvitations:number;queuedAi:number;runningAi:number;openFeedback:number}
const value=ref<Overview|null>(null),error=ref(''),busy=ref(false);
async function load(){busy.value=true;error.value='';try{value.value=(await api.get<Overview>('/admin/overview')).data;}catch(e){error.value=apiMessage(e);value.value=null;}finally{busy.value=false;}}onMounted(load);
</script>
<template><div class="page"><header class="page-head"><div><h1>管理总览</h1><p>这里只汇总账号与服务元数据，不读取成员的私人计划、对话或备份正文。</p></div><button class="btn" :disabled="busy" @click="load">刷新总览</button></header><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">正在读取管理摘要…</p>
<template v-if="value"><p class="helper-text">读取时间 {{new Date(value.observedAt).toLocaleString('zh-CN')}} · 当前快照，不代表历史趋势或活跃人数</p><dl class="admin-metrics"><div v-for="(label,key) in {members:'账号总数',enabledMembers:'启用账号',activeInvitations:'有效邀请',queuedAi:'AI等待请求',runningAi:'AI执行请求',openFeedback:'待处理反馈'}" :key="key"><dt>{{label}}</dt><dd>{{value[key]}}</dd></div></dl></template>
<div class="admin-entries"><router-link v-for="item in adminNavigation.slice(1)" :key="item.path" :to="item.path"><h2>{{item.label}}</h2><p>{{item.description}}</p></router-link></div></div></template>
<style scoped>.page-head p{margin:16px 0 0;color:var(--muted)}.admin-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:28px 0;border-top:1px solid var(--line);border-left:1px solid var(--line);background:#fff}.admin-metrics>div{padding:24px;border-bottom:1px solid var(--line);border-right:1px solid var(--line)}dt{font-size:.85rem;color:var(--muted)}dd{margin:12px 0 0;color:#002fa7;font-size:2.4rem;font-weight:700;font-variant-numeric:tabular-nums}.admin-entries{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.admin-entries a{padding:24px;background:#fff;border:1px solid var(--line);text-decoration:none;color:var(--ink)}.admin-entries h2{font-size:1.2rem}.admin-entries p{font-size:.85rem;color:var(--muted);margin:0}@media(max-width:700px){.admin-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.admin-metrics>div{padding:16px}.admin-entries{grid-template-columns:1fr;gap:12px}.page-head{gap:16px;align-items:start}}</style>
